<?php
namespace App\Filament\Resources\TeachingAssignments;
use App\Models\TeachingAssignment; use App\Filament\Resources\TeachingAssignments\Pages; use Filament\Forms\Components\{Select,TextInput}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\{Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table}; use BackedEnum; use UnitEnum;
class TeachingAssignmentResource extends Resource { protected static ?string $slug='teaching-assignments'; protected static ?string $model=TeachingAssignment::class; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedAcademicCap; protected static string|UnitEnum|null $navigationGroup='Penjadwalan & Ruang'; protected static ?string $navigationLabel='Dosen Pengampu'; protected static ?string $modelLabel='Dosen Pengampu'; protected static ?string $pluralModelLabel='Dosen Pengampu'; public static function form(Schema $schema):Schema{return $schema->components([Select::make('course_class_id')->label('Kelas')->relationship('courseClass','class_code')->searchable()->preload()->required(),Select::make('lecturer_id')->label('Dosen')->relationship('lecturer','nidn')->searchable()->preload()->required(),Select::make('role')->label('Peran')->options(['primary'=>'Dosen Utama','co'=>'Co-Dosen'])->default('primary')->required(),TextInput::make('teaching_load')->label('Beban Mengajar')->numeric()->minValue(0)->default(1),Select::make('status')->label('Status')->options(['active'=>'Aktif','inactive'=>'Tidak Aktif'])->default('active')->required()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('courseClass.class_code')->label('Kelas'),TextColumn::make('lecturer.user.name')->label('Dosen'),TextColumn::make('role')->label('Peran')->badge(),TextColumn::make('teaching_load')->label('Beban'),TextColumn::make('status')->label('Status')->badge()])->actions([EditAction::make()->label('Ubah'),DeleteAction::make()->label('Hapus')->requiresConfirmation()]);} public static function getPages():array{return ['index'=>Pages\ListTeachingAssignments::route('/'),'create'=>Pages\CreateTeachingAssignment::route('/create'),'edit'=>Pages\EditTeachingAssignment::route('/{record}/edit')];}}
